from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    chars = list(dict.fromkeys(alphabet))
    idx = {c: i for i, c in enumerate(chars)}
    k = len(chars)

    # Build the Aho-Corasick trie
    goto = [[-1] * k]
    bad = [False]
    for word in banned:
        node = 0
        for c in word:
            j = idx[c]
            if goto[node][j] == -1:
                goto.append([-1] * k)
                bad.append(False)
                goto[node][j] = len(goto) - 1
            node = goto[node][j]
        bad[node] = True

    # Compute failure links and complete the transition function
    m = len(goto)
    fail = [0] * m
    queue = deque()
    for j in range(k):
        v = goto[0][j]
        if v == -1:
            goto[0][j] = 0
        else:
            fail[v] = 0
            queue.append(v)
    while queue:
        u = queue.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for j in range(k):
            v = goto[u][j]
            if v == -1:
                goto[u][j] = goto[fail[u]][j]
            else:
                fail[v] = goto[fail[u]][j]
                queue.append(v)

    # Transition matrix restricted to states that do not contain a banned string
    safe = [s for s in range(m) if not bad[s]]
    pos = {s: i for i, s in enumerate(safe)}
    size = len(safe)
    if 0 not in pos:
        return 0

    T = [[0] * size for _ in range(size)]
    for u in safe:
        for j in range(k):
            v = goto[u][j]
            if not bad[v]:
                T[pos[u]][pos[v]] += 1

    def mat_mul(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for t in range(size):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(size):
                        Ci[j] += a * Bt[j]
            for j in range(size):
                Ci[j] %= MOD
        return C

    def vec_mul(r, A):
        out = [0] * size
        for i in range(size):
            ri = r[i]
            if ri:
                Ai = A[i]
                for j in range(size):
                    out[j] += ri * Ai[j]
        return [x % MOD for x in out]

    # Fast exponentiation applied to the starting vector
    vec = [0] * size
    vec[pos[0]] = 1
    power = T
    e = n
    while e:
        if e & 1:
            vec = vec_mul(vec, power)
        e >>= 1
        if e:
            power = mat_mul(power, power)

    return sum(vec) % MOD
